const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const reservoirLocation = ee.Geometry.Point([-107.1847, 33.1547]); // Elephant Butte Reservoir
  const region = reservoirLocation.buffer(5000); // 5km buffer around the reservoir

  // Date ranges (±15 days around target dates)
  const date1986 = {start: '1986-05-28', end: '1986-06-26'};
  const date2020 = {start: '2020-05-25', end: '2020-06-23'};

  // 2. Data Acquisition
  // Landsat 5 for 1986
  let landsat5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(region)
    .filterDate(date1986.start, date1986.end)
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  // Landsat 8 for 2020  
  let landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate(date2020.start, date2020.end)
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  // Check collection sizes
  const size1986 = landsat5.size().getInfo();
  const size2020 = landsat8.size().getInfo();

  console.log(`1986 Images: ${size1986}, 2020 Images: ${size2020}`);

  if (size1986 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get least cloudy images
  const img1986 = landsat5.sort('CLOUD_COVER').first();
  const img2020 = landsat8.sort('CLOUD_COVER').first();

  // 3. Processing - Calculate NDWI for water detection
  function calculateNDWI(image) {
    // For Landsat 5: Green = B2, NIR = B4
    // For Landsat 8: Green = B3, NIR = B5
    const green = image.select('SR_B2'); // Works for both L5 and L8
    const nir = image.select('SR_B4');   // Works for both L5 and L8

    const ndwi = green.subtract(nir).divide(green.add(nir)).rename('NDWI');
    return image.addBands(ndwi);
  }

  const ndwi1986 = calculateNDWI(img1986);
  const ndwi2020 = calculateNDWI(img2020);

  // Create water mask (NDWI > 0.2)
  const water1986 = ndwi1986.select('NDWI').gt(0.2);
  const water2020 = ndwi2020.select('NDWI').gt(0.2);

  // 4. Calculate water areas
  const waterStats1986 = water1986.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), null, true),
    geometry: region,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const waterStats2020 = water2020.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), null, true),
    geometry: region,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const waterArea1986 = waterStats1986.NDWI_sum;
  const waterArea2020 = waterStats2020.NDWI_sum;
  const totalPixels1986 = waterStats1986.NDWI_count;
  const totalPixels2020 = waterStats2020.NDWI_count;

  console.log(`1986 - Water pixels: ${waterArea1986}, Total pixels: ${totalPixels1986}`);
  console.log(`2020 - Water pixels: ${waterArea2020}, Total pixels: ${totalPixels2020}`);

  // 5. Validation & Final Answer
  if (waterArea1986 === null || waterArea2020 === null || 
      isNaN(waterArea1986) || isNaN(waterArea2020) ||
      totalPixels1986 === 0 || totalPixels2020 === 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate water percentage
  const waterPercent1986 = (waterArea1986 / totalPixels1986 * 100).toFixed(1);
  const waterPercent2020 = (waterArea2020 / totalPixels2020 * 100).toFixed(1);

  console.log(`1986 Water coverage: ${waterPercent1986}%`);
  console.log(`2020 Water coverage: ${waterPercent2020}%`);

  // Check if water extent decreased
  if (waterArea2020 < waterArea1986) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
